-- M09 增量设计；MySQL 8.0.16+；DDL隐式提交；报错停止，不使用force或自动重跑。
-- 同连接显式设置 @m09_close_maintenance_confirmed=1, @m09_close_baseline_verified=1, @m09_close_backup_ref=已完成恢复验证的备份记录ID。
DELIMITER $$
CREATE PROCEDURE m09_close_install_20260911()
BEGIN
 IF DATABASE() IS NULL OR COALESCE(@m09_close_maintenance_confirmed,0)<>1 OR COALESCE(@m09_close_baseline_verified,0)<>1 OR CHAR_LENGTH(TRIM(COALESCE(@m09_close_backup_ref,'')))=0 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Maintenance, exact baseline and recoverable backup required';
 END IF;
 IF VERSION() NOT REGEXP '^8[.]' OR (SUBSTRING_INDEX(VERSION(),'.',2)='8.0' AND CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(VERSION(),'.',3),'.',-1) AS UNSIGNED)<16) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MySQL 8.0.16+ with enforced CHECK required';
 END IF;
 IF (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('alarm_mail_config','alarm_notify_receiver','alarm_notify_rule','alarm_record','lab_offline_alarm_config','lab_status_alarm_config','sys_notification','alarm_online_config','alarm_monitor_policy','alarm_config_revision','alarm_event','alarm_recipient','alarm_delivery','alarm_delivery_attempt','alarm_runtime'))<>284 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Baseline column count mismatch; inspect exact schema';
 END IF;
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='alarm_config_revision' AND column_name='decision_snapshot') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Target column exists; inspect partial install'; END IF;
 IF EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='alarm_config_revision' AND column_name='application_receipt') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Target column exists; inspect partial install'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_notify_rule` WHERE (notify_mode IN ('0','1','2')) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_mode: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_notify_rule` WHERE (active_revision_id IS NULL OR (window_policy IS NOT NULL AND window_policy='NO_CATCH_UP' AND rule_key IS NOT NULL AND (notify_mode='0' OR (notify_limit_count IS NOT NULL AND notify_limit_count BETWEEN 1 AND 98 AND notify_interval_min IS NOT NULL AND notify_interval_min BETWEEN 1 AND 1439)))) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_rule_ready: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_mail_config` WHERE (server_port BETWEEN 1 AND 65535) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_port: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_notify_receiver` WHERE (receiver_source IN ('1','2','3') AND (receiver_source<>'3' OR (source_id IS NOT NULL AND source_id>0))) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_receiver_source: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_record` WHERE (handle_status IN ('0','1')) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_handle: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_record` WHERE (row_version IS NULL OR (row_version>=1 AND event_id IS NOT NULL AND episode_no IS NOT NULL AND episode_no>=1 AND condition_state IS NOT NULL AND condition_state IN ('ACTIVE','RESOLVED') AND recipient_state IS NOT NULL AND recipient_state IN ('RESOLVED','KNOWN_EMPTY','UNKNOWN'))) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_alarm_states: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_record` WHERE (row_version IS NULL OR condition_state<>'RESOLVED' OR resolved_at IS NOT NULL) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_resolved: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_event` WHERE (process_state IN ('RECEIVED','APPLIED','IGNORED','BLOCKED') AND event_kind IN ('TRIGGER','RECOVER','BUSINESS','EXTERNAL_PUSH')) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_event_state: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_event` WHERE (event_kind NOT IN ('TRIGGER','RECOVER') OR (condition_key IS NOT NULL AND source_sequence IS NOT NULL AND source_sequence>=0)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_condition: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_event` WHERE (JSON_TYPE(payload_json)='OBJECT' AND (result_ref IS NULL OR JSON_TYPE(result_ref)='OBJECT')) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_event_json: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_delivery` WHERE (delivery_state IN ('PENDING','SENDING','SUCCEEDED','FAILED','UNKNOWN','SKIPPED','CANCELLED') AND round_no>=1 AND attempt_count>=0 AND row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_delivery_state: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_delivery` WHERE ((target_kind='USER' AND channel IN ('site','email','sms')) OR (target_kind='SOUND' AND channel='sound') OR (target_kind='EXTERNAL' AND channel='external')) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_channel: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_delivery` WHERE (((lease_token IS NULL AND lease_until IS NULL) OR (lease_token IS NOT NULL AND lease_until IS NOT NULL)) AND (delivery_state<>'SENDING' OR lease_token IS NOT NULL)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_delivery_lease: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_delivery` WHERE (((address_cipher IS NULL AND address_key_version IS NULL) OR (address_cipher IS NOT NULL AND address_key_version IS NOT NULL)) AND ((content_cipher IS NULL AND content_key_version IS NULL) OR (content_cipher IS NOT NULL AND content_key_version IS NOT NULL))) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_cipher: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_delivery_attempt` WHERE (attempt_state IN ('INVOKING','SUCCEEDED','FAILED','UNKNOWN') AND attempt_no>=1 AND (finished_at IS NULL OR finished_at>=started_at)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_attempt: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_delivery_attempt` WHERE (attempt_state NOT IN ('SUCCEEDED','FAILED') OR finished_at IS NOT NULL) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_attempt_terminal: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_runtime` WHERE (condition_state IN ('NORMAL','ACTIVE','RESOLVED') AND notify_eligibility IN ('ELIGIBLE','RECORD_ONLY','STOPPED') AND latest_source_sequence>=0 AND episode_no>=0 AND rounds_created>=0 AND row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_runtime: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_runtime` WHERE (condition_state<>'ACTIVE' OR (active_alarm_id IS NOT NULL AND episode_no>=1 AND first_trigger_at IS NOT NULL)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_active: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_monitor_policy` WHERE (monitor_mode IN ('ON','TEMP_OFF','LONG_OFF') AND row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_monitor: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_config_revision` WHERE (config_kind IN ('RULE','MAIL','ONLINE','OFFLINE','STATUS','MONITOR') AND revision_state IN ('PENDING','APPLIED','DISCARDED','CONFLICT') AND row_version>=1 AND JSON_TYPE(content_json)='OBJECT' AND (revision_state<>'APPLIED' OR applied_at IS NOT NULL)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_revision: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_recipient` WHERE (user_id>0 AND JSON_TYPE(source_json)='OBJECT' AND COALESCE(JSON_TYPE(JSON_EXTRACT(source_json,'$.sources')),'MISSING')='ARRAY' AND JSON_TYPE(authorization_ref)='OBJECT') IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_recipient: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_online_config` WHERE ((scope_kind='DEVICE' AND culture_id IS NULL) OR (scope_kind='CULTURE' AND culture_id IS NOT NULL AND culture_id>0)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_online_scope: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_online_config` WHERE ((lower_limit IS NULL OR upper_limit IS NULL OR lower_limit<upper_limit) AND (limit_percent IS NULL OR limit_percent>0)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_online_limits: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_online_config` WHERE (enabled IN ('0','1') AND cycle_enabled IN ('0','1') AND evaluation_state IN ('SAVE_ONLY','VERIFIED') AND (evaluation_state<>'VERIFIED' OR logic_profile_ref IS NOT NULL)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_online_mode: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_online_config` WHERE ((stagnant_seconds IS NULL OR stagnant_seconds>=0) AND (upper_delay_seconds IS NULL OR upper_delay_seconds>=0) AND (lower_delay_seconds IS NULL OR lower_delay_seconds>=0) AND (cycle_seconds IS NULL OR cycle_seconds>=0) AND (cycle_enabled<>'1' OR (cycle_seconds IS NOT NULL AND cycle_seconds>0))) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_online_time: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_event` WHERE (row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_ver_event: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_monitor_policy` WHERE (row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_ver_monitor_policy: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `alarm_online_config` WHERE (row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_ver_online_config: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `lab_offline_alarm_config` WHERE (row_version IS NULL OR row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_ver_lab_offline_alarm_config: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `lab_status_alarm_config` WHERE (row_version IS NULL OR row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_ver_lab_status_alarm_config: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `sys_notification` WHERE (row_version IS NULL OR row_version>=1) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_ver_sys_notification: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `lab_offline_alarm_config` WHERE (row_version IS NULL OR (culture_id IS NOT NULL AND culture_id>0 AND revision_id IS NOT NULL AND active_key IS NOT NULL AND enabled IS NOT NULL AND enabled IN ('0','1') AND (lower_limit IS NULL OR upper_limit IS NULL OR lower_limit<upper_limit))) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_offline_ready: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `lab_status_alarm_config` WHERE (row_version IS NULL OR (revision_id IS NOT NULL AND (alarm_quantity IS NULL OR alarm_quantity>=0) AND alarm_operator IS NOT NULL AND alarm_operator='<')) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_status_ready: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `sys_notification` WHERE (is_read IS NULL OR is_read IN ('0','1')) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_notification_read: existing data violates target'; END IF;
 IF EXISTS(SELECT 1 FROM `sys_notification` WHERE (row_version IS NULL OR (target_user_id IS NOT NULL AND target_user_id>0 AND is_read IS NOT NULL)) IS FALSE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='ck_m09_close_notification_ready: existing data violates target'; END IF;

ALTER TABLE `alarm_config_revision` ADD COLUMN `decision_snapshot` JSON NULL COMMENT 'M06最终决定或DIRECT政策证据';
ALTER TABLE `alarm_config_revision` ADD COLUMN `application_receipt` JSON NULL COMMENT '当前候选的不可变生效或永久封禁回执';
ALTER TABLE `alarm_notify_rule` ADD CONSTRAINT `ck_m09_close_mode` CHECK (notify_mode IN ('0','1','2'));
ALTER TABLE `alarm_notify_rule` ADD CONSTRAINT `ck_m09_close_rule_ready` CHECK (active_revision_id IS NULL OR (window_policy IS NOT NULL AND window_policy='NO_CATCH_UP' AND rule_key IS NOT NULL AND (notify_mode='0' OR (notify_limit_count IS NOT NULL AND notify_limit_count BETWEEN 1 AND 98 AND notify_interval_min IS NOT NULL AND notify_interval_min BETWEEN 1 AND 1439))));
ALTER TABLE `alarm_mail_config` ADD CONSTRAINT `ck_m09_close_port` CHECK (server_port BETWEEN 1 AND 65535);
ALTER TABLE `alarm_notify_receiver` ADD CONSTRAINT `ck_m09_close_receiver_source` CHECK (receiver_source IN ('1','2','3') AND (receiver_source<>'3' OR (source_id IS NOT NULL AND source_id>0)));
ALTER TABLE `alarm_record` ADD CONSTRAINT `ck_m09_close_handle` CHECK (handle_status IN ('0','1'));
ALTER TABLE `alarm_record` ADD CONSTRAINT `ck_m09_close_alarm_states` CHECK (row_version IS NULL OR (row_version>=1 AND event_id IS NOT NULL AND episode_no IS NOT NULL AND episode_no>=1 AND condition_state IS NOT NULL AND condition_state IN ('ACTIVE','RESOLVED') AND recipient_state IS NOT NULL AND recipient_state IN ('RESOLVED','KNOWN_EMPTY','UNKNOWN')));
ALTER TABLE `alarm_record` ADD CONSTRAINT `ck_m09_close_resolved` CHECK (row_version IS NULL OR condition_state<>'RESOLVED' OR resolved_at IS NOT NULL);
ALTER TABLE `alarm_event` ADD CONSTRAINT `ck_m09_close_event_state` CHECK (process_state IN ('RECEIVED','APPLIED','IGNORED','BLOCKED') AND event_kind IN ('TRIGGER','RECOVER','BUSINESS','EXTERNAL_PUSH'));
ALTER TABLE `alarm_event` ADD CONSTRAINT `ck_m09_close_condition` CHECK (event_kind NOT IN ('TRIGGER','RECOVER') OR (condition_key IS NOT NULL AND source_sequence IS NOT NULL AND source_sequence>=0));
ALTER TABLE `alarm_event` ADD CONSTRAINT `ck_m09_close_event_json` CHECK (JSON_TYPE(payload_json)='OBJECT' AND (result_ref IS NULL OR JSON_TYPE(result_ref)='OBJECT'));
ALTER TABLE `alarm_delivery` ADD CONSTRAINT `ck_m09_close_delivery_state` CHECK (delivery_state IN ('PENDING','SENDING','SUCCEEDED','FAILED','UNKNOWN','SKIPPED','CANCELLED') AND round_no>=1 AND attempt_count>=0 AND row_version>=1);
ALTER TABLE `alarm_delivery` ADD CONSTRAINT `ck_m09_close_channel` CHECK ((target_kind='USER' AND channel IN ('site','email','sms')) OR (target_kind='SOUND' AND channel='sound') OR (target_kind='EXTERNAL' AND channel='external'));
ALTER TABLE `alarm_delivery` ADD CONSTRAINT `ck_m09_close_delivery_lease` CHECK (((lease_token IS NULL AND lease_until IS NULL) OR (lease_token IS NOT NULL AND lease_until IS NOT NULL)) AND (delivery_state<>'SENDING' OR lease_token IS NOT NULL));
ALTER TABLE `alarm_delivery` ADD CONSTRAINT `ck_m09_close_cipher` CHECK (((address_cipher IS NULL AND address_key_version IS NULL) OR (address_cipher IS NOT NULL AND address_key_version IS NOT NULL)) AND ((content_cipher IS NULL AND content_key_version IS NULL) OR (content_cipher IS NOT NULL AND content_key_version IS NOT NULL)));
ALTER TABLE `alarm_delivery_attempt` ADD CONSTRAINT `ck_m09_close_attempt` CHECK (attempt_state IN ('INVOKING','SUCCEEDED','FAILED','UNKNOWN') AND attempt_no>=1 AND (finished_at IS NULL OR finished_at>=started_at));
ALTER TABLE `alarm_delivery_attempt` ADD CONSTRAINT `ck_m09_close_attempt_terminal` CHECK (attempt_state NOT IN ('SUCCEEDED','FAILED') OR finished_at IS NOT NULL);
ALTER TABLE `alarm_runtime` ADD CONSTRAINT `ck_m09_close_runtime` CHECK (condition_state IN ('NORMAL','ACTIVE','RESOLVED') AND notify_eligibility IN ('ELIGIBLE','RECORD_ONLY','STOPPED') AND latest_source_sequence>=0 AND episode_no>=0 AND rounds_created>=0 AND row_version>=1);
ALTER TABLE `alarm_runtime` ADD CONSTRAINT `ck_m09_close_active` CHECK (condition_state<>'ACTIVE' OR (active_alarm_id IS NOT NULL AND episode_no>=1 AND first_trigger_at IS NOT NULL));
ALTER TABLE `alarm_monitor_policy` ADD CONSTRAINT `ck_m09_close_monitor` CHECK (monitor_mode IN ('ON','TEMP_OFF','LONG_OFF') AND row_version>=1);
ALTER TABLE `alarm_config_revision` ADD CONSTRAINT `ck_m09_close_revision` CHECK (config_kind IN ('RULE','MAIL','ONLINE','OFFLINE','STATUS','MONITOR') AND revision_state IN ('PENDING','APPLIED','DISCARDED','CONFLICT') AND row_version>=1 AND JSON_TYPE(content_json)='OBJECT' AND (revision_state<>'APPLIED' OR applied_at IS NOT NULL));
ALTER TABLE `alarm_recipient` ADD CONSTRAINT `ck_m09_close_recipient` CHECK (user_id>0 AND JSON_TYPE(source_json)='OBJECT' AND COALESCE(JSON_TYPE(JSON_EXTRACT(source_json,'$.sources')),'MISSING')='ARRAY' AND JSON_TYPE(authorization_ref)='OBJECT');
ALTER TABLE `alarm_online_config` ADD CONSTRAINT `ck_m09_close_online_scope` CHECK ((scope_kind='DEVICE' AND culture_id IS NULL) OR (scope_kind='CULTURE' AND culture_id IS NOT NULL AND culture_id>0));
ALTER TABLE `alarm_online_config` ADD CONSTRAINT `ck_m09_close_online_limits` CHECK ((lower_limit IS NULL OR upper_limit IS NULL OR lower_limit<upper_limit) AND (limit_percent IS NULL OR limit_percent>0));
ALTER TABLE `alarm_online_config` ADD CONSTRAINT `ck_m09_close_online_mode` CHECK (enabled IN ('0','1') AND cycle_enabled IN ('0','1') AND evaluation_state IN ('SAVE_ONLY','VERIFIED') AND (evaluation_state<>'VERIFIED' OR logic_profile_ref IS NOT NULL));
ALTER TABLE `alarm_online_config` ADD CONSTRAINT `ck_m09_close_online_time` CHECK ((stagnant_seconds IS NULL OR stagnant_seconds>=0) AND (upper_delay_seconds IS NULL OR upper_delay_seconds>=0) AND (lower_delay_seconds IS NULL OR lower_delay_seconds>=0) AND (cycle_seconds IS NULL OR cycle_seconds>=0) AND (cycle_enabled<>'1' OR (cycle_seconds IS NOT NULL AND cycle_seconds>0)));
ALTER TABLE `alarm_event` ADD CONSTRAINT `ck_m09_close_ver_event` CHECK (row_version>=1);
ALTER TABLE `alarm_monitor_policy` ADD CONSTRAINT `ck_m09_close_ver_monitor_policy` CHECK (row_version>=1);
ALTER TABLE `alarm_online_config` ADD CONSTRAINT `ck_m09_close_ver_online_config` CHECK (row_version>=1);
ALTER TABLE `lab_offline_alarm_config` ADD CONSTRAINT `ck_m09_close_ver_lab_offline_alarm_config` CHECK (row_version IS NULL OR row_version>=1);
ALTER TABLE `lab_status_alarm_config` ADD CONSTRAINT `ck_m09_close_ver_lab_status_alarm_config` CHECK (row_version IS NULL OR row_version>=1);
ALTER TABLE `sys_notification` ADD CONSTRAINT `ck_m09_close_ver_sys_notification` CHECK (row_version IS NULL OR row_version>=1);
ALTER TABLE `lab_offline_alarm_config` ADD CONSTRAINT `ck_m09_close_offline_ready` CHECK (row_version IS NULL OR (culture_id IS NOT NULL AND culture_id>0 AND revision_id IS NOT NULL AND active_key IS NOT NULL AND enabled IS NOT NULL AND enabled IN ('0','1') AND (lower_limit IS NULL OR upper_limit IS NULL OR lower_limit<upper_limit)));
ALTER TABLE `lab_status_alarm_config` ADD CONSTRAINT `ck_m09_close_status_ready` CHECK (row_version IS NULL OR (revision_id IS NOT NULL AND (alarm_quantity IS NULL OR alarm_quantity>=0) AND alarm_operator IS NOT NULL AND alarm_operator='<'));
ALTER TABLE `sys_notification` ADD CONSTRAINT `ck_m09_close_notification_read` CHECK (is_read IS NULL OR is_read IN ('0','1'));
ALTER TABLE `sys_notification` ADD CONSTRAINT `ck_m09_close_notification_ready` CHECK (row_version IS NULL OR (target_user_id IS NOT NULL AND target_user_id>0 AND is_read IS NOT NULL));
END$$
DELIMITER ;
CALL m09_close_install_20260911();
DROP PROCEDURE m09_close_install_20260911;
